const Module = require('module');
const originalLoad = Module._load;
const refs = [];
const cleanups = [];
let hook = 0;
const React = {
  useRef(value) {
    const index = hook++;
    if (!refs[index]) refs[index] = { current: value };
    return refs[index];
  },
  useReducer() { hook++; return [0, () => {}]; },
  useEffect(effect) { cleanups.push(effect()); },
};
Module._load = function(request, parent, isMain) {
  if (request === 'react') return React;
  return originalLoad.call(this, request, parent, isMain);
};
const { usePreparation } = require('./src/usePreparation.js');
const api = require('./src/preparation-api.js');
let requests = [];
let retries = [];
let cancelled = [];
globalThis.__preparationTransport = (token) => new Promise((resolve) => requests.push({ token, resolve }));
globalThis.__schedulePreparationRetry = (callback) => {
  const handle = { callback };
  retries.push(handle);
  return handle;
};
globalThis.__cancelPreparationRetry = (handle) => cancelled.push(handle);
const tick = () => new Promise((resolve) => setImmediate(resolve));
function mount() { hook = 0; return usePreparation('first', { invalidateOnClose: true }); }
(async () => {
  const dialog = mount();
  dialog.start();
  assert.equal(requests.length, 1);
  requests[0].resolve(api.PREPARATION_STATUS.PENDING);
  await tick();
