  assert.equal(dialog.snapshot().completed.length, 0);
  retries[0].callback();
  assert.equal(requests.length, 2);

  dialog.close();
  requests[1].resolve(api.PREPARATION_STATUS.READY);
  await tick();
  assert.deepEqual(dialog.snapshot().completed, []);
  assert.equal(dialog.snapshot().loading, false);

  dialog.reopen('second');
  assert.equal(requests.length, 3);
  requests[2].resolve(api.PREPARATION_STATUS.PENDING);
  await tick();
  const staleRetry = retries[1];
  dialog.reopen('third');
  assert.equal(requests.length, 4);
  staleRetry.callback();
  assert.equal(requests.length, 4);
  requests[3].resolve(api.PREPARATION_STATUS.READY);
  await tick();
  assert.deepEqual(dialog.snapshot().completed, ['third']);

  cleanups.forEach((cleanup) => cleanup && cleanup());
  console.log('usePreparation lifecycle polling assertions passed');
})().catch((error) => { console.error(error); process.exitCode = 1; });
